@module fs  src=fs.lua  loc=123  mode=namespace  self=fs

# Shapes
  @shape  fileOps = { copy(src,dst)->bool, move(src,dst)->bool, mkdir(dir), exists(path)->bool, hash(path)->string }  @ 109

# Imports
  @const util = 'util'  @ 5
      @invariant  sole module touching reaper.Enumerate* and filesystem IO; UI/view layers route through here  @ 3
      @invariant  listDirs and listAudioFiles return case-insensitively sorted output (Finder/Explorer parity)  @ 4

# Module-level constants
  @const fs = {}  @ 7
  @const AUDIO_EXTS = {  @ 9

# Private functions
  @fn ciLess(a, b)  @ 36
  @fn copyFile(src, dst)  @ 97-107
      -- 64KB chunks so big samples don't allocate a Lua string the size of the file.

# Functions held in tables
  @held fileOps.move(src, dst)  @ 113-117
  @held fileOps.mkdir(dir)  @ 118

# Public API (fs.*)
  @api fs.isAudio(name)  @ 14-18
  @api fs.basename(path)  @ 20-22
  @api fs.parent(path)  @ 25-27
      @contract  returns '' if path has no separator; trailing separators on input are not stripped (caller passes canonical paths)  @ 24
  @api fs.join(a, b)  @ 30-34
      @contract  inserts '/' between a and b unless a already ends in '/' or '\\'; no path normalisation  @ 29
  @api fs.listDirs(path)  @ 39-49
      @contract  hides dotfile-prefixed entries (.git, .DS_Store, etc.)  @ 38
  @api fs.exists(path)  @ 51-55
  @api fs.readText(path)  @ 57-60
  @api fs.hashFile(path)  @ 63-82
      @contract  FNV-1a over (size, first 4KB, last 4KB); 8-char hex; non-cryptographic; see docs/fs.md  @ 62
  @api fs.listAudioFiles(path)  @ 84-94

# Uses (outbound edges)
  @use call    util.add  @ listDirs:44 listAudioFiles:89
  @use require util  @ <load>:5

# Calls (intra-file)
  @call copyFile  @ fileOps.move:115
  @call fs.isAudio  @ listAudioFiles:89

# Bindings (by name)
  @bind ciLess  @ listDirs:47 listAudioFiles:92
  @bind copyFile  @ 111

# Unresolved receivers
  @drop a:lower  @ ciLess:36
  @drop a:sub  @ join:31
  @drop b:lower  @ ciLess:36
  @drop data:byte  @ hashFile:79
  @drop ext:lower  @ isAudio:17
  @drop f:close  @ exists:53 readText:59 hashFile:75
  @drop f:read  @ readText:59 hashFile:69,73
  @drop f:seek  @ hashFile:66,67,68,72
  @drop fin:close  @ copyFile:99,105
  @drop fin:read  @ copyFile:101
  @drop fout:close  @ copyFile:105
  @drop fout:write  @ copyFile:103
  @drop name:match  @ isAudio:15
  @drop path:match  @ basename:21 parent:26
  @drop sub:sub  @ listDirs:44

# REAPER API surface
  @reaper EnumerateSubdirectories
  @reaper EnumerateFiles
  @reaper RecursiveCreateDirectory

# Fields (r read / w write incl. constructor keys)
  @field w aif  @ 10
  @field w aiff  @ 10
  @field w basename  @ basename:20
  @field w copy  @ 111
  @field r exists  @ 119
  @field w exists  @ exists:51 119
  @field w fileOps  @ 110
  @field w flac  @ 10
  @field w hash  @ 120
  @field r hashFile  @ 120
  @field w hashFile  @ hashFile:63
  @field w isAudio  @ isAudio:14
  @field w join  @ join:30
  @field w listAudioFiles  @ listAudioFiles:84
  @field w listDirs  @ listDirs:39
  @field w m4a  @ 11
  @field w mkdir  @ fileOps.mkdir:118
  @field w move  @ fileOps.move:113
  @field w mp3  @ 11
  @field w ogg  @ 11
  @field w opus  @ 11
  @field w parent  @ parent:25
  @field w readText  @ readText:57
  @field w wav  @ 10
